  public static final PhonAdapter<TerminalContentResult> ADAPTER = new PhonAdapter<>() {
    @Override public SchemaClosure schema() { return SCHEMA_CLOSURE; }
    @Override public void encode(PhonEncoder encoder, TerminalContentResult value) throws PhonException {
      encoder.writeString(value.sessionId());
      encoder.writeI64(value.sequence());
      encoder.writeString(value.text());
      encoder.writeBool(value.complete());
      encoder.writeBool(value.truncated());
      encoder.writeAdapted(TerminalPromptMetadata.ADAPTER, value.prompt());
    }
    @Override public TerminalContentResult decode(PhonDecoder decoder) throws PhonException { return new TerminalContentResult(decoder.readString(), decoder.readI64(), decoder.readString(), decoder.readBool(), decoder.readBool(), decoder.readAdapted(TerminalPromptMetadata.ADAPTER)); }
  };

  @Override public boolean equals(Object other) {
    if (!(other instanceof TerminalContentResult that)) return false;
    return Objects.deepEquals(sessionId, that.sessionId) && Objects.deepEquals(sequence, that.sequence) && Objects.deepEquals(text, that.text) && Objects.deepEquals(complete, that.complete) && Objects.deepEquals(truncated, that.truncated) && Objects.deepEquals(prompt, that.prompt);
  }
  @Override public int hashCode() { return Objects.hash(sessionId, sequence, text, complete, truncated, prompt); }
  @Override public String toString() { return "TerminalContentResult" + java.util.List.of(sessionId, sequence, text, complete, truncated, prompt); }
